const monthCounts = `-- name: MonthCounts :one
SELECT
    (SELECT count(*) FROM disputes.disputes d WHERE d.merchant_id = $1 AND d.livemode = $2 AND d.kind = 'chargeback'
        AND d.created_at >= $3 AND d.created_at < $4)::bigint AS disputes,
    (SELECT count(*) FROM disputes.fraud_reports f WHERE f.merchant_id = $1 AND f.livemode = $2
        AND f.reported_at >= $3 AND f.reported_at < $4)::bigint AS fraud_reports
`

type MonthCountsParams struct {
	MerchantID string
	Livemode   bool
	FromTime   pgtype.Timestamptz
	ToTime     pgtype.Timestamptz
}

type MonthCountsRow struct {
	Disputes     int64
	FraudReports int64
}

// A merchant's card disputes opened and fraud reports received in a period.
func (q *Queries) MonthCounts(ctx context.Context, arg MonthCountsParams) (MonthCountsRow, error) {
	row := q.db.QueryRow(ctx, monthCounts,
		arg.MerchantID,
		arg.Livemode,
		arg.FromTime,
		arg.ToTime,
	)
	var i MonthCountsRow
	err := row.Scan(&i.Disputes, &i.FraudReports)
	return i, err
}

const overdueResponses = `-- name: OverdueResponses :many
SELECT id FROM disputes.disputes
WHERE status = 'needs_response' AND due_by < $1 AND pending_action = ''
ORDER BY due_by, id
LIMIT 500
`

// Disputes whose merchant's deadline passed with no answer.
func (q *Queries) OverdueResponses(ctx context.Context, now pgtype.Timestamptz) ([]string, error) {
	rows, err := q.db.Query(ctx, overdueResponses, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

