const stuckDisputes = `-- name: StuckDisputes :many
SELECT id, status, pending_action, action_error FROM disputes.disputes
WHERE (status IN ('needs_response', 'under_review') AND network_due_by < $1)
   OR (pending_action <> '' AND updated_at < $1)
ORDER BY id
LIMIT 1000
`

type StuckDisputesRow struct {
	ID            string
	Status        string
	PendingAction string
	ActionError   string
}

// Disputes open past the network's deadline by more than a grace, or with an action the
// network or bank has refused to take for that long.
func (q *Queries) StuckDisputes(ctx context.Context, before pgtype.Timestamptz) ([]StuckDisputesRow, error) {
	rows, err := q.db.Query(ctx, stuckDisputes, before)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StuckDisputesRow{}
	for rows.Next() {
		var i StuckDisputesRow
		if err := rows.Scan(
			&i.ID,
			&i.Status,
			&i.PendingAction,
			&i.ActionError,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const toRefresh = `-- name: ToRefresh :many
SELECT id FROM disputes.disputes
WHERE pending_action = '' AND (status IN ('needs_response', 'under_review'))
  AND (network_due_by < $1 OR updated_at < $2)
ORDER BY updated_at, id
LIMIT 500
`

type ToRefreshParams struct {
	Now        pgtype.Timestamptz
	QuietSince pgtype.Timestamptz
}

// Open disputes to ask the network or the bank about: past the deadline Jupiter has with
// them, or quiet for a while.
func (q *Queries) ToRefresh(ctx context.Context, arg ToRefreshParams) ([]string, error) {
	rows, err := q.db.Query(ctx, toRefresh, arg.Now, arg.QuietSince)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
